	/**
	 * Default Constructor
	 */
    public PurchaseOrderService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new PurchaseOrderEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(PurchaseOrderRepository.class) );
		this.validator		= applicationContext.getBean(PurchaseOrderValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		PurchaseOrder
	 */
		public PurchaseOrder createPurchaseOrder( CreatePurchaseOrderCommand command ) {

		PurchaseOrder entity = new PurchaseOrder();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setPurchaseOrderId( command.getPurchaseOrderId() );
            entity.setPoNumber( command.getPoNumber() );
            entity.setOrderDate( command.getOrderDate() );
            entity.setTotalAmount( command.getTotalAmount() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of PurchaseOrder {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdatePurchaseOrderCommand
	 * @return		PurchaseOrder
	 */
	public PurchaseOrder updatePurchaseOrder( UpdatePurchaseOrderCommand command ) {

		PurchaseOrder entity = new PurchaseOrder();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setPurchaseOrderId( command.getPurchaseOrderId() );
            entity.setPoNumber( command.getPoNumber() );
            entity.setOrderDate( command.getOrderDate() );
            entity.setTotalAmount( command.getTotalAmount() );
            entity.setSupplier( command.getSupplier() );
            entity.setPlant( command.getPlant() );
            entity.setLines( command.getLines() );
            entity.setGoodsReceipts( command.getGoodsReceipts() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of PurchaseOrder {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeletePurchaseOrderCommand
	 */
	public void delete( DeletePurchaseOrderCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getPurchaseOrderId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of PurchaseOrder {0} ", id );

	}

	/**
	 * Method to retrieve the PurchaseOrder via PurchaseOrderFetchOneSummary
	 * @param 	summary PurchaseOrderFetchOneSummary
	 * @return 	PurchaseOrderFetchOneResponse
	 */
	public PurchaseOrder getPurchaseOrder( PurchaseOrderFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "PurchaseOrderFetchOneSummary arg cannot be null" );

		PurchaseOrder entity = null;
		UUID id = summary.getPurchaseOrderId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a PurchaseOrder using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all PurchaseOrders
	 *
	 * @return 	List<PurchaseOrder>
	 */
    public List<PurchaseOrder> getAllPurchaseOrder() {
		List<PurchaseOrder> list = projector.findAll( new FindAllPurchaseOrderQuery() );
		return list;
	}

	/**
	 * assign Supplier on PurchaseOrder
	 * @param		command AssignSupplierToPurchaseOrderCommand
	 */
	public void assignSupplier( AssignSupplierToPurchaseOrderCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignSupplier(command.getPurchaseOrderId(), command.getAssignment());

	}

